VALUES (28156, 'tt0069754', NULL, 'The Baby', 'The Baby', 'movie', 1973, 'https://image.tmdb.org/t/p/w500/ovk7WxoO5Bu970qGCQuF6DgrwZw.jpg', 'https://image.tmdb.org/t/p/original/f2iMBg9Z1LGxuzzVvBhgdUU0ECR.jpg', 'A social worker who recently lost her husband investigates the strange Wadsworth family. The Wadsworths might not seem too unusual to hear about them at first - consisting of the mother, two grown daughters and the diaper-clad, bottle-sucking baby. The problem is, the baby is twenty-one years old.', NULL, NULL, 1.647, 5.9, 0, 9.51, '2026-10-27 20:58:06', '2026-10-27 20:58:06')
