VALUES (123, 'tt0077869', NULL, 'The Lord of the Rings', 'The Lord of the Rings', 'movie', 1978, 'https://image.tmdb.org/t/p/w500/liW0mjvTyLs7UCumaHhx3PpU4VT.jpg', 'https://image.tmdb.org/t/p/original/TXSxV23MWYkezZ3219gtgcSX6n.jpg', 'Young Hobbit Frodo Baggins is thrown into an amazing adventure when he''s tasked with destroying the One Ring, created by the dark lord Sauron. Frodo must travel in a small fellowship of nine warriors and accomplices. But it won''t be an easy journey for the Fellowship of the Ring, on the ultimate quest to rid Middle-earth of evil.', NULL, NULL, 6.5023, 6.591, 0, 15.3875, '2026-07-15 12:01:52', '2026-10-27 20:58:06')
