VALUES (2433, 'tt0062873', NULL, 'The Young Girls of Rochefort', 'Les Demoiselles de Rochefort', 'movie', 1967, 'https://image.tmdb.org/t/p/w500/jtxhyGaYhurH6KsjvP1jV3dDypz.jpg', 'https://image.tmdb.org/t/p/original/8m7qOKlsdnxt4335vpFzpffuIVu.jpg', 'In the seaside town of Rochefort, twin sisters Delphine and Solange dream of love and artistic fulfillment beyond their quiet lives. As sailors, artists, musicians, and chance visitors pass through town during a weekend fair, a web of near-misses and romantic longing brings ideal partners tantalizingly close—without their realizing it.', NULL, NULL, 5.1906, 7.662, 0, 1.60323076923076932e+01, '2026-07-15 12:01:52', '2026-10-27 20:58:06')
