VALUES (329, 'tt0107290', NULL, 'Jurassic Park', 'Jurassic Park', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/d9mtMGQDLANKieb9PbD3yK7xxzo.jpg', 'https://image.tmdb.org/t/p/original/4SyDTF02R5BepqSdQmOaNCHObzF.jpg', 'A wealthy entrepreneur secretly creates a theme park featuring living dinosaurs drawn from prehistoric DNA. Before opening day, he invites a team of experts and his two eager grandchildren to experience the park and help calm anxious investors. However, the park is anything but amusing as the security systems go off-line and the dinosaurs escape.', NULL, NULL, 14.6276, 7.978, 0, 3.16196428571428569e+01, '2026-07-20 04:02:06', '2026-10-27 20:58:06')
