VALUES (7514, 'tt0070155', NULL, 'The Harder They Come', 'The Harder They Come', 'movie', 1972, 'https://image.tmdb.org/t/p/w500/nXcWgfds0E8T2pQLvgWLCiUmlV6.jpg', 'https://image.tmdb.org/t/p/original/4VMuH97CPGqsVBtuGWltp5BeyNj.jpg', 'Ivanhoe Martin arrives in Kingston, Jamaica, looking for work and, after some initial struggles, lands a recording contract as a reggae singer. He records his first song, "The Harder They Come," but after a bitter dispute with a manipulative producer named Hilton, soon finds himself resorting to petty crime in order to pay the bills. He deals marijuana, kills some abusive cops and earns local folk hero status. Meanwhile, his record is topping the charts.', NULL, NULL, 1.4674, 6.58, 0, 6.3875, '2026-08-03 14:31:56', '2026-10-27 20:58:06')
