VALUES (24684, 'tt1174732', NULL, 'An Education', 'An Education', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/gLIvvUdlocGjm8XVLxhWHAKWrRq.jpg', 'https://image.tmdb.org/t/p/original/9Cw5fOWLfHwFHjg88dC5oBZEmL4.jpg', 'Despite her sheltered upbringing, Jenny is a teen with a bright future; she''s smart, pretty, and has aspirations of attending Oxford University. When David, a charming but much older suitor, motors into her life in a shiny automobile, Jenny gets a taste of adult life that she won''t soon forget.', NULL, NULL, 3.7999, 6.93, 0, 8.596, '2026-08-04 03:20:13', '2026-10-27 20:58:06')
