VALUES (10822, 'tt0379976', NULL, 'Savage Grace', 'Savage Grace', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/rtJp4ulwC1SvSYAUFGUa1pWV7nk.jpg', 'https://image.tmdb.org/t/p/original/xDVLCGKjJK8wRgTQKZLOevlFoTp.jpg', 'This examination of a famous scandal from the 1970s explores the relationship between Barbara Baekeland and her only son, Antony. Barbara, a lonely social climber unhappily married to the wealthy but remote plastics heir Brooks Baekeland, dotes on Antony, who is homosexual. As Barbara tries to "cure" Antony of his sexuality -- sometimes by seducing him herself -- the groundwork is laid for a murderous tragedy.', NULL, NULL, 2.3196, 5.657, 0, 6.77, '2026-08-05 03:13:48', '2026-10-27 20:58:06')
